-- 438: SOL（p21）2026-09-15 Beyond Next Ventures 定例で出た知見を、会議カード・技術台帳・コスト試算（廃液・燃料）へ反映する
--
--   会議: 2026-09-15 10:00–11:00 SolvioraX <> Beyond Next Ventures 定例（Zoom）。Notion の文字起こし
--        https://app.notion.com/p/SolvioraX-Beyond-Next-Ventures-3dc97749c608809da7e3f5266c33569b を読んでまとめた。
--   ① 会議カード（project_meeting_summaries）を1件入れる（Notion の PJ を SOL に紐づけたが、取り込み待ちなので手で入れる）
--   ② 技術台帳（project_tech_entries）に杉浦先生の口頭報告を足す・直す
--        pH2 の鉄系排液でも改良株で浄化し中性に戻る／実排液（磁性材料）でレアアースを取り込み／食品系排液で BOD・COD の用途／
--        燃料系の会社の排液で増殖が約4倍／脂肪酸 12〜13%（乾燥重量比）／メタノールで細胞破砕と抽出が同時／乾燥は要らない／
--        分泌株の文献値は別の生きもの・特許要確認／屋外培養は P1・改変が難航／培地の緩衝剤が輸入品で9割超／透明プラ容器の納期／
--        カートリッジ型装置で取り込み実験・逆流洗浄が1時間に5分
--   ③ コスト試算（廃液・燃料）: 前提「排液で増える速さの倍率」（waste_medium_growth_factor、4倍）を足す。
--        排液を培地に使えるとき（waste_medium が on）だけ効き、培養設備1系列で年に作れる量に掛ける（計算は画面の変更 v3.140.0 で入る）
--   ④ コスト試算（燃料）: FAME ポテンシャルを杉浦先生の分析値 12〜13% で置き直す（低位 8・基準 12・改善 13）。
--        細胞破砕設備を 0円（メタノールで壊れる）、抽出溶媒をメタノール 50円/kg、破砕の電力を外し 0.1kWh/kg、保守を 37.5億円の3% に
--   数字（円/L、基準・委託、切り替えすべて OFF）: 15,657.4 → 7,785.8。排液・排熱・排ガスの3つを使うと 1,421.4（倍率1）→ 1,163.0（倍率4）
--   数字（円/m³、自然株・オンサイト・直接投入）: 3つを使うとき 金属回収 241.4 → 209.5、色素分解 37.6 → 32.9（OFF は 913.2 / 135.0 のまま）
-- 画面と計算の変更（waste_medium_growth_factor を読む v3.140.0）の配信が済んでから適用すること。
-- 生成: えいみ 2026-09-15（SOLセッション）。fixture（scripts/__fixtures__/sx_cost_model_two_stage.json・sx_fuel_cost_model.json）と同じ値を書く。
begin;
select set_config('amd.cost_change_reason', '438: 2026-09-15 BNV定例の杉浦先生の報告を反映。排液で培養が約4倍速く増える倍率の前提を足し（排液を培地に使うときだけ効く）、燃料は FAME ポテンシャルを分析値 12〜13% に置き直し、メタノールで細胞破砕と抽出が同時に済むので破砕設備を0円・溶媒をメタノール・破砕の電力を外した', true);

do $do$ begin
  if exists (select 1 from project_cost_assumptions where cost_assumption_id in ('ca19_waste_medium_growth', 'caf_waste_medium_growth')) then raise exception '438: 前提 waste_medium_growth がもうある'; end if;
  if exists (select 1 from project_cost_assumptions where role_key = 'waste_medium_growth_factor') then raise exception '438: role waste_medium_growth_factor がもうある'; end if;
  if exists (select 1 from project_cost_notes where cost_note_id in ('cn19_h19', 'cnf_history_bnv0915')) then raise exception '438: 注記がもうある'; end if;
  if exists (select 1 from project_cost_questions where cost_question_id in ('cq19_01', 'cqf_extraction_methanol', 'cqf_secretion_patent')) then raise exception '438: 確認事項がもうある'; end if;
  if exists (select 1 from project_meeting_summaries where meeting_id = '2f4bv3trdpk3hhg7l5k5pg4hi4_20260915T010000Z') then raise exception '438: 会議カードがもうある'; end if;
  if exists (select 1 from project_tech_entries where tech_entry_id like 'pte_sx_0915_%') then raise exception '438: 技術台帳の行がもうある'; end if;
  if (select value from project_cost_assumptions where cost_assumption_id = 'caf_fame_potential') is distinct from 6 then raise exception '438: FAMEポテンシャル（基準）が確認した時点（6）から変わっている'; end if;
  if (select unit_price from project_cost_items where cost_item_id = 'cif_plant_disruption') is distinct from 400000000 then raise exception '438: 細胞破砕設備の単価が確認した時点から変わっている'; end if;
  if (select quantity from project_cost_items where cost_item_id = 'cif_op_power') is distinct from 0.3 then raise exception '438: 電力の量が確認した時点から変わっている'; end if;
  if (select unit_price from project_cost_items where cost_item_id = 'cif_op_solvent') is distinct from 200 then raise exception '438: 溶媒の単価が確認した時点から変わっている'; end if;
  if (select unit_price from project_cost_items where cost_item_id = 'cif_op_maintenance') is distinct from 124500000 then raise exception '438: 保守の額が確認した時点から変わっている'; end if;
end $do$;

