-- ④ 燃料: FAME ポテンシャル（杉浦先生の分析値 12〜13%）
update project_cost_assumptions set value = 12, confidence = 'B', source_kind = '実測', owner = '杉浦先生', updated_at = now(),
  note = '乾燥菌体を分析したときに得られるFAME（脂肪酸メチルエステル。バイオディーゼルの成分）の重さの割合。2026-09-15 から、杉浦先生の分析値「細胞の乾燥重量あたり脂肪酸 12〜13%（世界最高水準）」（Beyond Next Ventures 定例）の下側で置く。分析はできているが、そこから実際に取り出す実験はこれから。前の額 6% は細胞の膜の量から積み上げた試算（膜の脂質だけで、油を貯めない天然の株）で、実測がそれを上回った。メタノールから加わるメチル基の分は入れていない（脂肪酸の重さのまま）。'
  where cost_assumption_id = 'caf_fame_potential';
update project_cost_assumptions set value = 8, updated_at = now(),
  note = '低位。細胞の膜の量から積み上げた試算の上側（光合成の膜が多い菌体で約7.8%）。2026-09-15 の実測 12〜13% が出る前の「改善」の値で、培養の条件で脂肪酸が減ったときの置き方。前の額は 4%（膜が少ない菌体の試算）。'
  where cost_assumption_id = 'caf_fame_potential_low';
update project_cost_assumptions set value = 13, confidence = 'B', source_kind = '実測', owner = '杉浦先生', updated_at = now(),
  note = '改善。杉浦先生の分析値 12〜13%（2026-09-15）の上側。統計的な上限や将来予測ではない。前の額は 8%（膜の量からの試算の上側）。'
  where cost_assumption_id = 'caf_fame_potential_high';

-- ④ 燃料: メタノールで細胞破砕と抽出が同時に済む
update project_cost_items set unit_price = 0, updated_at = now(),
  note = '0円（2026-09-15 から）。杉浦先生「シアノバクテリアは細胞壁が弱く、抽出のときメタノールを入れたら全部壊れる。細胞を壊す工程と抽出する工程は同義語になる」（Beyond Next Ventures 定例）。高圧ホモジナイザーなどの破砕設備は要らない前提にし、前の額 400,000,000円/式（湿った菌体の細胞破砕の目安、見積なし）を説明に残す。藻類（細胞壁が硬い）の工場と違うところ。'
  where cost_item_id = 'cif_plant_disruption';
update project_cost_items set quantity = 0.1, updated_at = now(),
  note = '乾燥菌体1kgあたり0.1kWh（2026-09-15 から。前の額 0.3kWh は細胞破砕が大部分だった）。メタノールで細胞が壊れるので破砕の動力を外し、脱水・抽出のポンプの分だけ残した目安（見積なし）。単価は特別高圧の産業用電力の全国平均 17.45円/kWh（2026年5月、新電力ネット）。'
  where cost_item_id = 'cif_op_power';
update project_cost_items set unit_price = 50, leaf_label = 'メタノール（回収できない分）', mid_label = '抽出溶媒（メタノール）の補給', updated_at = now(),
  note = '溶媒はメタノールに決めた（2026-09-15 杉浦先生。細胞を壊す工程と抽出が同時に済む）。量は2026-09-07 の工程とマテバラ推定（循環する溶媒 2,850kg のうち99%を回収し、乾燥菌体1tあたり28.5kgを補給）。単価は FAME にする段のメタノールと同じ 50円/kg（アジアのスポット 約318ドル/t）で、前の額 200円/kg は溶媒未決の仮置き。先生の案では、FAME にする段（2段目）で使ったメタノールを抽出（1段目）に回すので、補給はさらに減る。メタノールは価格の変動が大きく、2026-09 時点で高い（先生）。'
  where cost_item_id = 'cif_op_solvent';
update project_cost_items set unit_price = 112500000, leaf_label = '燃料化設備（脱水・油回収・残渣・出荷）の初期投資の3%/年', updated_at = now(),
  note = '燃料化設備1系列の初期投資（37.5億円。2026-09-15 に細胞破砕設備 4億円を0円にした後）の3%/年。初期投資の明細を書き換えたら、この額も合わせて直す。脱水・油回収の設備の保守。脂質分泌株では別の設備の保守を数える。前の額 124,500,000円（41.5億円の3%）。'
  where cost_item_id = 'cif_op_maintenance';

