update project_cost_questions set status = 'answered', answer = '杉浦先生の分析で、細胞の乾燥重量あたり脂肪酸 12〜13%（世界最高水準）。取り出す実験はこれから（2026-09-15 BNV定例）。基準 12・改善 13・低位 8% で置いた。', answered_on = '2026-09-15', updated_at = now() where cost_question_id = 'cqf_fame_potential';
insert into project_cost_questions (cost_model_id, cost_question_id, addressee, question, why_it_matters, impact_low, impact_high, status, linked_assumption_id, visibility, sort_order) values
('cm_p21_fuel_260914', 'cqf_extraction_methanol', '杉浦先生', 'メタノールで細胞を壊しながら脂肪酸を取り出すとき、①乾燥菌体1kgあたりメタノールを何L使いますか ②取り出せる脂肪酸の割合（12〜13%のうち何割）③使ったメタノールをどれくらい回収して使い回せますか ④乾燥せず、フィルターで集めた湿った菌体のままで進められますか。まだ分からなければ、確かめる実験の条件と回数を教えてください。', '2026-09-15 から、細胞破砕設備を0円、抽出溶媒をメタノール 50円/kg で置いている。取り出せる割合（脂質抽出回収率 90%）と回収率（99%）はマテバラ推定の仮置きで、SX 株の実測ではない。取り出せる割合が半分なら燃料1Lに要る菌体が2倍になり、基準・委託は 7,785.8 → 約15,000円/L。', 0, 7800, 'open', 'caf_fame_potential', 'amd_internal', 12),
('cm_p21_fuel_260914', 'cqf_secretion_patent', 'AMD内部', '脂質（脂肪酸）を培養液へ分泌するシアノバクテリアの株が、特許で押さえられていないかを調べる。名古屋大学の先生（理研時代の杉浦先生の先輩）が見つけたものと、Kato ら（改変 Synechococcus）の系統について。', '脂質分泌株の試算（1,598.3円/L、3つの切り替えで 1,129.1円/L）は、SX でその株を作れる前提。特許で押さえられていれば、作っても使えないか許諾料が要る（2026-09-15 BNV定例で武田氏・杉浦先生）。', 0, 0, 'open', 'caf_lipid_secretion', 'amd_internal', 18),
('cm_p21_260820', 'cq19_01', '杉浦先生', '排液を培地にすると増殖が約4倍速い（2026-09-15）とのことでしたが、①どの排液で、②光・温度・CO2 は普段の培養と同じ条件でしたか。③大きい槽（光が届きにくい）でも同じくらい速くなりそうですか。①4倍に近い ②2倍くらい ③あまり変わらない ④まだ分からない。', '前提「排液で増える速さの倍率」（4倍）は、培養設備の系列の数を通して効く。自然株・オンサイト・直接投入で排液・排熱・排ガスを使うとき、金属回収は倍率1で 241.4円/m³、4で 209.5円/m³。色素分解は 37.6 → 32.9円/m³。実験室の観察なので、大きい槽での値で置き直す。', 0, 32, 'open', 'ca19_waste_medium_growth', 'amd_internal', 370);

-- ② 技術台帳
update project_tech_entries set value_text = '酸性排水はpH2〜5が多いとの現場情報。pH2.6の鉄模擬排液で単回成立。pH2の鉄系の実排液でも、改良株を使えば浄化して水が中性に戻る（2026-09-15 杉浦先生の口頭報告、データは未取得）', condition_text = '現場情報と鉄模擬排液の単回試験、実排液での口頭報告を併記', observed_on = '2026-09-15', source_ref = 'SX 定例報告会_260902 / 2026-09-15 SolvioraX <> Beyond Next Ventures 定例（Notion文字起こし）', needs_check = true, check_reason = 'pH2 の実排液の結果は口頭報告のみ。株・濃さ・時間・中性に戻るまでの経過のデータを受け取る', updated_at = now(), updated_by = 'amie' where tech_entry_id = 'pte_sx_l14';
update project_tech_entries set value_text = '○ Dy・Ndの取り込みを確認 (速報)。磁性材料メーカーの実排液でも取り込みを確認し、濃い液での実証へ（NDA を先方から依頼、2026-09-14）', condition_text = 'Dy・Ndの水溶液に細胞を入れ、3時間後には液中のレアアースがほぼなくなった (2026-07-10 杉浦先生)。実排液は、偶然レアアースを含んでいた磁性材料メーカーの排液（2026-09-15 口頭報告。濃さ・取り込み量は未記録）', observed_on = '2026-09-15', source_ref = '2026-07-10 杉浦先生 Slack / 2026-09-15 SolvioraX <> Beyond Next Ventures 定例（Notion文字起こし）', needs_check = true, check_reason = '実排液のレアアースの濃さと取り込み量のデータを受け取る', updated_at = now(), updated_by = 'amie' where tech_entry_id = 'pte_sx_e07';
update project_tech_entries set value_text = 'pH2.6の鉄模擬排液で成立した単回試験あり。pH2の鉄系の実排液でも改良株で浄化し中性に戻る（2026-09-15 口頭報告）。現場の酸性排水はpH2〜5が多い', condition_text = '模擬排液は培地成分を含まない水とFe(NO₃)₃のみの液。実排液の結果はデータ未取得', observed_on = '2026-09-15', source_ref = 'SX 定例報告会_260902 / 2026-09-15 BNV定例', updated_at = now(), updated_by = 'amie' where tech_entry_id = 'pte_sx_ss04';
update project_tech_entries set value_text = '銅 / 鉄 / ニッケル / 反応性窒素 / 色素 / 鉛・Dy・Nd (速報) / レアアース（磁性材料メーカーの実排液、2026-09-15 口頭報告）', observed_on = '2026-09-15', source_ref = '2026-09-14 までの記録 / 2026-09-15 BNV定例', updated_at = now(), updated_by = 'amie' where tech_entry_id = 'pte_sx_ss14';
insert into project_tech_entries (tech_entry_id, tech_topic_id, project_id, row_label, col_label, value_min, value_max, value_text, unit, rating, condition_text, observed_on, confidence, source_kind, source_ref, source_url, note, sort_order, created_by, updated_by, needs_check, check_reason) values
('pte_sx_0915_01', 'ptt_sx_elements', 'p21', '有機物（BOD・COD）', null, null, null, '○ 試験中。食品系排液で菌体が増え、BOD・CODを下げる用途に使える可能性', null, null, 'いよぎん紹介の食品関係の排液。2026-09-14 から COD を継続測定する装置で測り始めた。増えた理由は排液の窒素とみている（糖は炭素源にならない）', '2026-09-15', 'medium', 'meeting', '2026-09-15 SolvioraX <> Beyond Next Ventures 定例（Notion文字起こし）', 'https://app.notion.com/p/SolvioraX-Beyond-Next-Ventures-3dc97749c608809da7e3f5266c33569b', '重金属だけでなく、食品工場が困っている BOD・COD の低減が3つ目の用途になりうる（杉浦先生）', 135, 'amie', 'amie', true, 'COD の測定結果（処理前後）を受け取る'),
('pte_sx_0915_02', 'ptt_sx_record', 'p21', '実排液の試験数', null, 18, null, '18種類以上の実排液を試験し、処理できるもの・pHが低くて難しいもの・こうすればできるものを記録中', '種', null, '伊予銀行などの紹介で排液をもらえるようになった 2026-07 以降の累計', '2026-09-15', 'medium', 'meeting', '2026-09-15 BNV定例（Notion文字起こし）', null, '業種ごとに「こうやればきれいになる」のデータを蓄積中（杉浦先生）', 170, 'amie', 'amie', true, '18種類の一覧（会社・液・結果）を技術台帳へ写す'),
('pte_sx_0915_03', 'ptt_sx_record', 'p21', 'カートリッジ型装置での取り込み試験', null, null, null, '協力企業が作った大型のカートリッジ型（細胞を外に出さない）で取り込み試験を開始。数時間で目詰まりするので、1時間に5分ほどの逆流洗浄が要る', null, null, 'それまでは槽に入れる型で試験していた。運転中', '2026-09-15', 'medium', 'meeting', '2026-09-15 BNV定例（Notion文字起こし）', null, '逆流洗浄はオンサイトでは顧客の運転なので、コスト試算の SX の原価には入れていない', 175, 'amie', 'amie', true, '逆流洗浄の頻度と時間、目詰まりまでの時間のデータを受け取る'),
('pte_sx_0915_04', 'ptt_sx_record', 'p21', 'pH2 の鉄系実排液の処理', null, 2, null, '改良株を使えば、あっという間にきれいになり、最後に水が中性に戻った（杉浦先生「衝撃的」）', 'pH', null, '鉄系の実排液。株・濃さ・時間は口頭報告のみ', '2026-09-15', 'medium', 'meeting', '2026-09-15 BNV定例（Notion文字起こし）', null, 'それまで、pH の低いところではシアノバクテリアは始められないと考えられていた', 176, 'amie', 'amie', true, 'データ（pH の推移・鉄の濃さ・時間）を受け取る'),
('pte_sx_0915_05', 'ptt_sx_record', 'p21', '燃料系の会社の排液で培養', null, 4, null, '見た目にも臭くて色のついた排液に菌体を入れると、今まで見たことのない速度で増えた（約4倍、1日で）。窒素酸化物・硫黄酸化物を栄養にしている', '倍', null, '協力の申し出があった石油系の燃料の会社の排液。排熱と排ガスも出る工場', '2026-09-15', 'medium', 'meeting', '2026-09-15 BNV定例（Notion文字起こし）', null, '培養装置は排液・排熱・排ガスが出る工場の中に置くのがいちばん安い、という見立ての根拠。コスト試算の前提「排液で増える速さの倍率」（4倍）に置いた', 177, 'amie', 'amie', true, '排液あり・なしの増殖曲線（g/L/日）を受け取る'),
('pte_sx_0915_06', 'ptt_sx_culture', 'p21', '排液を培地にしたときの増殖', null, 4, null, '約4倍速く増えた（1日で）', '倍', null, '燃料系の会社の排液。窒素酸化物・硫黄酸化物が栄養になる。光・温度・CO2 の条件は未記録', '2026-09-15', 'medium', 'meeting', '2026-09-15 BNV定例（Notion文字起こし）', null, '2026-01-20 の「工場の排ガスで培養したとき」（倍加時間 約6時間）と別の観察', 106.5, 'amie', 'amie', true, '同じ条件で排液あり・なしを比べたデータを受け取る'),
('pte_sx_0915_07', 'ptt_sx_culture', 'p21', '培地の費用の内訳（緩衝剤）', null, null, null, '培地の費用の9割超が緩衝剤で、輸入品のため価格の変動が大きい。安いものへ置き換え中。排液を培地にすればほぼゼロ', null, null, '研究室の培地（2026-09 時点）', '2026-09-15', 'medium', 'meeting', '2026-09-15 BNV定例（Notion文字起こし）', null, 'コスト試算の培地の原料（窒素源・リン源・カリウムなど）には緩衝剤の行が無い', 121, 'amie', 'amie', false, null),
('pte_sx_0915_08', 'ptt_sx_culture', 'p21', '透明容器の入手', null, null, null, '培養容器は光を通す透明のプラスチックが要る。通常1週間の納期が1〜2か月かかり、研究の予定を遅らせている主因', null, null, '2026-09 時点。戦争の影響とされる。ナフサそのものは減っていないと大手素材メーカー', '2026-09-15', 'medium', 'meeting', '2026-09-15 BNV定例（Notion文字起こし）', null, 'メタノールの価格も上がっている（燃料の抽出・FAME 化で使う）', 122, 'amie', 'amie', false, null),
('pte_sx_0915_09', 'ptt_sx_culture', 'p21', '屋外培養', null, null, null, '遺伝子組み換え株なので屋外では培養できない（封じ込め P1 なら許可を取って建てられる）。屋外で培養できる改変を進めているが難航中', null, null, '2026-09 時点', '2026-09-15', 'medium', 'meeting', '2026-09-15 BNV定例（Notion文字起こし）', null, 'ユーグレナなど藻類は屋外の池で培養する。この差が設備費（CAPEX）の差になる', 113, 'amie', 'amie', false, null),
('pte_sx_0915_10', 'ptt_sx_biofuel', 'p21', '脂肪酸の量（分析値）', null, 12, 13, '細胞の乾燥重量あたり 12〜13%（世界最高水準）', '%', null, '分析値。取り出す実験はこれから', '2026-09-15', 'high', 'meeting', '2026-09-15 BNV定例（Notion文字起こし）', null, 'コスト試算（燃料）の FAME ポテンシャルを 低位8・基準12・改善13% に置き直した根拠。前は細胞の膜の量からの試算（4 / 6 / 8%）', 70, 'amie', 'amie', true, '分析の方法・回数・株・培養条件を受け取る'),
('pte_sx_0915_11', 'ptt_sx_biofuel', 'p21', '抽出の方法（メタノール）', null, null, null, 'シアノバクテリアは細胞壁が弱く、メタノールを入れるだけで細胞が壊れて抽出が同時に済む。乾燥は考えておらず、フィルターで集めた菌体にメタノールを入れる', null, null, '杉浦先生の想定。実験はこれから', '2026-09-15', 'medium', 'meeting', '2026-09-15 BNV定例（Notion文字起こし）', null, '藻類は細胞壁が硬く破砕に費用がかかる。コスト試算（燃料）の細胞破砕設備を0円、溶媒をメタノールにした根拠', 72, 'amie', 'amie', true, 'メタノールの量・取り出せる割合・回収率を実験で確かめる'),
('pte_sx_0915_12', 'ptt_sx_biofuel', 'p21', 'メタノールの使い回し', null, null, null, 'メタノールは抽出と FAME 化の2段階で使う。2段階目で使ったものを1段階目に回せば費用が下がる（試算はしていない）', null, null, '杉浦先生の案', '2026-09-15', 'low', 'meeting', '2026-09-15 BNV定例（Notion文字起こし）', null, null, 74, 'amie', 'amie', true, '回せる割合を実験で確かめる'),
('pte_sx_0915_13', 'ptt_sx_biofuel', 'p21', '脂質分泌株の見立て', null, null, null, '分泌する株を持つ他の先生の株は、室温でしか生きず、糖が要り、量も乾燥細胞あたり 1/4〜1/6 なので取り込むメリットは無い。高熱性シアノの遺伝子組み換えは杉浦研でしかできない。特許で押さえられていないかは要調査', null, null, '名古屋大学の先生（理研時代の先輩）の株について', '2026-09-15', 'medium', 'meeting', '2026-09-15 BNV定例（Notion文字起こし）', null, 'コスト試算（燃料）の分泌速度の文献値（0.036 g/L/日）は改変 Synechococcus の研究室の値', 76, 'amie', 'amie', true, '特許を調べる（確認事項 cqf_secretion_patent）'),
('pte_sx_0915_14', 'ptt_sx_spec_sheet', 'p21', '【生み出せるもの】脂肪酸（燃料の元）', null, 12, 13, '細胞の乾燥重量あたり 12〜13%（分析値、世界最高水準）', '%', null, '取り出す実験はこれから。メタノールで細胞が壊れて抽出が同時に済む', '2026-09-15', 'high', 'meeting', '2026-09-15 BNV定例（Notion文字起こし）', null, null, 185, 'amie', 'amie', true, '分析の方法・回数を受け取る'),
('pte_sx_0915_15', 'ptt_sx_spec_sheet', 'p21', '【力を発揮する条件】排液を培地にしたとき', null, 4, null, '燃料系の会社の排液で約4倍速く増えた（窒素酸化物・硫黄酸化物が栄養）', '倍', null, '実験室の観察。大きい槽では光が律速になりうる', '2026-09-15', 'medium', 'meeting', '2026-09-15 BNV定例（Notion文字起こし）', null, null, 105, 'amie', 'amie', true, '同じ条件で比べたデータを受け取る'),
('pte_sx_0915_16', 'ptt_sx_spec_sheet', 'p21', '【株による違い】遺伝子組み換えのノウハウ', null, null, null, '技術そのものより「タイミングと選抜の仕方」にノウハウがあり、研究室内ではシステム化されている（卒業生はできる）。論文公開後も外部では再現できていない。特許は取っていないので、ビデオで言語化して守る', null, null, '2026-09-15 の合意（まさ・杉浦先生・BNV）', '2026-09-15', 'medium', 'meeting', '2026-09-15 BNV定例（Notion文字起こし）', null, '大量培養は外注できるが、遺伝子組み換えは自社（杉浦研）でしかできない', 285, 'amie', 'amie', false, null);

-- ① 会議カード
insert into project_meeting_summaries (meeting_id, project_id, ym, meeting_date, meeting_start_at, title, notion_url, notion_page_id, calendar_event_id, source_kinds, generated_by_model, generated_at, summary_short, decided, progress, next_actions, risks, narrative_md)
values (
'2f4bv3trdpk3hhg7l5k5pg4hi4_20260915T010000Z', 'p21', '202609', '2026-09-15', '2026-09-15 10:00+09', 'SolvioraX <> Beyond Next Ventures 定例',
'https://app.notion.com/p/SolvioraX-Beyond-Next-Ventures-3dc97749c608809da7e3f5266c33569b', '3dc97749-c608-809d-a7e3-f5266c33569b', '2f4bv3trdpk3hhg7l5k5pg4hi4_20260915T010000Z',
'notion+calendar', 'claude:fable-5.1（会議後にえいみが文字起こしから作成）', now(),
